import sys

def solve_brute(board):
    m, n = len(board), len(board[0])
    def can_escape(i, j, visited):
        if i < 0 or i >= m or j < 0 or j >= n:
            return True
        if board[i][j] == 'X' or (i, j) in visited:
            return False
        visited.add((i, j))
        return (can_escape(i + 1, j, visited) or can_escape(i - 1, j, visited) or
                can_escape(i, j + 1, visited) or can_escape(i, j - 1, visited))
    for i in range(m):
        for j in range(n):
            if board[i][j] == 'O':
                visited = set()
                if not can_escape(i, j, visited):
                    board[i][j] = 'X'
    return board

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    board = []
    idx = 2
    for _ in range(m):
        board.append([data[idx + j] for j in range(n)])
        idx += n
    board = solve_brute(board)
    for row in board:
        print(' '.join(row))

import sys

def solve_opt(board):
    m, n = len(board), len(board[0])
    def dfs(i, j):
        if i < 0 or i >= m or j < 0 or j >= n or board[i][j] != 'O':
            return
        board[i][j] = 'S'
        dfs(i + 1, j); dfs(i - 1, j); dfs(i, j + 1); dfs(i, j - 1)
    for i in range(m):
        for j in range(n):
            if (i == 0 or i == m - 1 or j == 0 or j == n - 1) and board[i][j] == 'O':
                dfs(i, j)
    for i in range(m):
        for j in range(n):
            if board[i][j] == 'O':
                board[i][j] = 'X'
            elif board[i][j] == 'S':
                board[i][j] = 'O'
    return board

