import sys

class UF:
    def __init__(self, n):
        self.p = list(range(n))
    def find(self, x):
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x
    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra != rb: self.p[ra] = rb

def solve_best(board):
    m, n = len(board), len(board[0])
    if m == 0 or n == 0: return board
    dummy = m * n
    uf = UF(m * n + 1)
    for i in range(m):
        for j in range(n):
            if board[i][j] == 'O':
                if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                    uf.union(i * n + j, dummy)
                for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                    ni, nj = i + di, j + dj
                    if 0 <= ni < m and 0 <= nj < n and board[ni][nj] == 'O':
                        uf.union(i * n + j, ni * n + nj)
    for i in range(m):
        for j in range(n):
            if board[i][j] == 'O' and uf.find(i * n + j) != uf.find(dummy):
                board[i][j] = 'X'
    return board

